Region Level Allocation
This is done by filtering the household projections to only total households (household_type_id == 0 and age_group_id == 0), joining to the HNA region crosswalk to get the region for each county, summarizing to get total households by year and region, then joining to the allocation table to get the percentages, and finally calculating the allocated households by multiplying total households by the percentage of households by tenure and percentage of households by AMI group within each tenure.


Show code
hh_ami_forecast_region &lt;- hh_projections |&gt;
  filter(
    area_code != 0,
    household_type_id == 0,
    age_group_id == 0
  ) |&gt;
  left_join(
    xwalk_hna_region |&gt;
      select(
        area_code = countyfips,
        region_code
      ) |&gt;
      mutate(region = str_sub(region_code, -1)),
    by = "area_code"
  ) |&gt;
  summarize(
    total_households = sum(total_households, na.rm = TRUE),
    .by = c(year, region)
  ) |&gt;
  left_join(
    hh_ami_tbls$hh_ami_allocation_tbl,
    by = c("year", "region")
  ) |&gt;
  mutate(
    hh_allocated = total_households * pct_hh_ten * pct_hh_ami_ten
  )

State Level Allocation
Next, the region level allocations are summed to the state level by summing across all regions for each year, tenure, and AMI group. Then the total households by year are calculated, followed by the percentages of households by tenure and by AMI group within each tenure.


Show code
hh_ami_forecast_state &lt;- hh_ami_forecast_region |&gt;
  summarize(
    region = "0",
    hh_allocated = sum(hh_allocated),
    .by = c(year, tenure, ami_group)
  ) |&gt;
  mutate(
    total_households = sum(hh_allocated),
    .by = year
  ) |&gt;
  mutate(
    pct_hh_ten = sum(hh_allocated) / total_households,
    pct_hh_ami_ten = hh_allocated / sum(hh_allocated),
    .by = c(year, tenure)
  )

hh_ami_forecast &lt;- bind_rows(
  hh_ami_forecast_state,
  hh_ami_forecast_region
) |&gt;
  arrange(year, region, tenure, ami_group)

Calculate AMI percentiles by year
Next we calculate the AMI percentiles by year. We do this by grouping the data by year, household type, AMI percentile, AMI group3, age group, cost burdened 30, cost burdened 50, tenure, tenure detail, and household size. We then calculate the total household weight for each group. We also join the median family income (MFI) for each year.


Show code
ami_parquet_files &lt;- list.files("data/ami_parquet/", full.names = TRUE)

create_acs_mfi_srvy_us &lt;- function(file) {
  acs_mfi_srvy_us &lt;- read_parquet_duckdb(file) |&gt;
    # collect() |&gt;
    filter(
      PERNUM == 1, # One record per household
      GQ %in% c(1, 2) # Households and group quarters
    ) |&gt;
    select(
      YEAR,
      PERNUM,
      GQ,
      ami_group,
      tenure,
      HHWT,
      RENT,
      OWNCOST,
      housing_cost,
      cost_burdened_30,
      cost_burdened_50
    ) |&gt;
    as_survey_design(
      weight = HHWT,
      type = "ACS",
      mse = TRUE
    )
}

calc_amis &lt;- function(acs_srvy) {
  ami_df &lt;- acs_srvy |&gt;
    group_by(YEAR, tenure, ami_group) |&gt;
    summarize(
      total_hh = survey_total(),
      cost_burdened_30 = survey_total(cost_burdened_30),
      cost_burdened_50 = survey_total(cost_burdened_50),
      .groups = "drop"
    ) |&gt;
    mutate(
      pct_cost_burdened_30 = cost_burdened_30 / total_hh,
      pct_cost_burdened_50 = cost_burdened_50 / total_hh
    )

  return(ami_df)
}

