# set up a multisession plan, then parallel map over files

plan(multisession, workers = parallel::detectCores() - 1)

process_file &lt;- function(file) {
  create_acs_mfi_srvy_us(file) |&gt; calc_amis()
}

hh_by_ten_ami_us &lt;- future_map_dfr(
  ami_parquet_files,
