Calculate AMI percentiles by year
Next we calculate the AMI percentiles by year. We do this by grouping the data by year, household type, AMI percentile, AMI group3, age group, cost burdened 30, cost burdened 50, tenure, tenure detail, and household size. We then calculate the total household weight for each group. We also join the median family income (MFI) for each year.


Show code
fn_calc_amis &lt;- function(df, hna_region) {
  srvy &lt;- df |&gt;
    filter(
      region == hna_region, # filter to region
      year &gt;= 2005, # remove years without puma data, skip 2000
      pernum == 1, # one record per household
      gq %in% c(1, 2) # households and group quarters
    ) |&gt;
    select(
      year,
      region,
      pernum,
      gq,
      ami_group,
      tenure,
      hhwt,
      rent,
      owncost,
      housing_cost,
      cost_burdened_30,
      cost_burdened_50,
      matches("repwt[0-9]+")
    ) |&gt;
    mutate(
      tenure = str_to_lower(str_extract(tenure, "Own|Rent"))
    ) |&gt;
    as_survey_design(
      weight = hhwt,
      repweights = matches("repwt[0-9]+"),
      type = "ACS",
      mse = TRUE
    )

  cost_burden_df &lt;- srvy |&gt;
    filter(!is.na(ami_group)) |&gt;
    group_by(year, region, ami_group, tenure) |&gt;
    summarize(
      total_hh = survey_total(),
      cost_burdened_30 = survey_total(cost_burdened_30),
      cost_burdened_50 = survey_total(cost_burdened_50),
      .groups = "drop"
    ) |&gt;
    mutate(
      total_hh_ten = sum(total_hh),
      .by = c(year, region, tenure)
    ) |&gt;
    mutate(
      pct_hh_ten = total_hh / total_hh_ten,
      pct_cost_burdened_30 = cost_burdened_30 / total_hh,
      pct_cost_burdened_50 = cost_burdened_50 / total_hh
    )

  rm(srvy)

  return(cost_burden_df)
}

cost_burden_by_ten_ami_region &lt;- map(
  as.character(1:4),
  \(x) fn_calc_amis(acs_amis_region, x),
  .progress = TRUE
) |&gt;
  bind_rows()




