Calculate AMI percentiles by year
Next we calculate the AMI percentiles by year. We do this by grouping the data by year, household type, AMI percentile, AMI group3, age group, cost burdened 30, cost burdened 50, tenure, tenure detail, and household size. We then calculate the total household weight for each group. We also join the median family income (MFI) for each year.


Show code
fn_calc_amis &lt;- function(
  df,
  hna_region = "0",
  primary_vars = c("ami_group", "tenure"),
  extra_vars = character(),
  cost_vars = c("cost_burdened_30", "cost_burdened_50")
) {
  base_select &lt;- c(
    "year",
    "region",
    "pernum",
    "gq",
    "hhwt",
    "rent",
    "owncost",
    "housing_cost"
  )

  # ensure inputs are character vectors (NULL -&gt; character(0))
  primary_vars &lt;- as.character(primary_vars)
  extra_vars &lt;- as.character(extra_vars)
  cost_vars &lt;- as.character(cost_vars)

  select_vars &lt;- unique(c(base_select, primary_vars, extra_vars, cost_vars))

  srvy &lt;- df |&gt;
    filter(
      region == hna_region,
      year &gt;= 2005,
      pernum == 1,
      gq %in% c(1, 2)
    ) |&gt;
    select(any_of(select_vars), matches("repwt[0-9]+")) |&gt;
    as_survey_design(
      weight = hhwt,
      repweights = matches("repwt[0-9]+"),
      type = "ACS",
      mse = TRUE
    )

  # which primary/extra vars actually exist in the survey variables
  available_vars &lt;- names(srvy$variables)
  primary_present &lt;- intersect(primary_vars, available_vars)
  extra_present &lt;- intersect(extra_vars, available_vars)

  # group columns: always include year/region, then the primary vars (those present), then extra vars (present)
  group_cols &lt;- unique(c("year", "region", primary_present, extra_present))
  group_cols &lt;- intersect(group_cols, available_vars)

  # build summarize expressions
  sum_exprs &lt;- list(total_hh = rlang::expr(survey_total()))
  present_costs &lt;- intersect(cost_vars, available_vars)
  for (cv in present_costs) {
    sum_exprs[[cv]] &lt;- rlang::expr(survey_total(!!rlang::sym(cv)))
  }

  cost_burden_df &lt;- srvy |&gt;
    filter(
      !!rlang::sym(ifelse(
        "ami_group" %in% available_vars,
        "ami_group",
        primary_present[1]
      )) %&gt;%
        is.na() %&gt;%
        `!`()
    ) |&gt;
    group_by(!!!rlang::syms(group_cols)) |&gt;
    summarize(!!!sum_exprs, .groups = "drop")

  # determine grouping for computing totals (year, region, plus denominator primary var if present, plus extra_vars)
  denom_var &lt;- if (length(primary_present) &gt;= 2) primary_present[2] else NULL
  total_by_cols &lt;- intersect(
    c("year", "region", denom_var, extra_present),
    names(cost_burden_df)
  )

  if (length(total_by_cols) &gt; 0) {
    cost_burden_df &lt;- cost_burden_df |&gt;
      group_by(!!!rlang::syms(total_by_cols)) |&gt;
      mutate(total_hh_ten = sum(total_hh)) |&gt;
      ungroup()
  } else {
    cost_burden_df &lt;- cost_burden_df |&gt;
      mutate(total_hh_ten = sum(total_hh))
  }

  # always compute pct_hh_ten (share of the denominator grouping)
  cost_burden_df &lt;- cost_burden_df |&gt;
    mutate(pct_hh_ten = total_hh / total_hh_ten)

  # compute cost-burden percentages only for requested/present cost vars
  if ("cost_burdened_30" %in% names(cost_burden_df)) {
    cost_burden_df &lt;- cost_burden_df |&gt;
      mutate(pct_cost_burdened_30 = cost_burdened_30 / total_hh)
  }
  if ("cost_burdened_50" %in% names(cost_burden_df)) {
    cost_burden_df &lt;- cost_burden_df |&gt;
      mutate(pct_cost_burdened_50 = cost_burdened_50 / total_hh)
  }

  rm(srvy)
  cost_burden_df
}




